/**
 * The rendered tree as text. A screen hands some hosts a React ELEMENT as a
 * prop (a ScrollView's refreshControl, a list's ListEmptyComponent), and an
 * element carries its owner fiber, which is circular. React's own fields are
 * left out, and an object met twice is written once.
 */
function treeText(tree: renderer.ReactTestRenderer): string {
  const seen = new WeakSet<object>();
  return JSON.stringify(tree.toJSON() ?? null, (key: string, value: unknown) => {
    if (key.startsWith('_')) return undefined;
    if (typeof value === 'object' && value !== null) {
      if (seen.has(value)) return undefined;
      seen.add(value);
    }
    return value;
  });
}

